/*
 * Markdown Viewer - Simple — bundled mini syntax highlighter.
 *
 * A small, dependency-free tokenizer exposing the same entry point as highlight.js
 * (window.hljs.highlightAll) and the same CSS classes (hljs-keyword, hljs-string, ...), so the
 * official highlight.js 11.x browser build (BSD-3-Clause) can replace this file later without
 * touching viewer.js or highlight.css. See README.md, "Replacing the bundled highlighter".
 *
 * Safety: works on textContent and rebuilds each code block from DOM text nodes and <span>s.
 * It never assigns innerHTML, so document text can never become markup.
 */
(function () {
  'use strict';

  function words(s) {
    var set = Object.create(null);
    s.split(/\s+/).forEach(function (w) { if (w) set[w] = true; });
    return set;
  }

  // ------------------------------------------------------------ token rules
  // Each rule: [className, stickyRegExp, options]. options.bol = only at the start of a line;
  // options.keepBol = the line still counts as "at start" after this token (YAML list dashes).

  var NUM = /(?:0[xX][0-9a-fA-F_]+|0[bB][01_]+|(?:\d[\d_]*\.?\d*|\.\d+)(?:[eE][+-]?\d+)?)[a-zA-Z]*/y;
  var DQ = /"(?:[^"\\\n]|\\.)*"?/y;
  var SQ = /'(?:[^'\\\n]|\\.)*'?/y;
  var BT = /`(?:[^`\\]|\\.)*`?/y;
  var LINE_SLASH = /\/\/.*/y;
  var BLOCK = /\/\*[\s\S]*?(?:\*\/|$)/y;
  var HASH = /#.*/y;
  var IDENT = /[A-Za-z_$][\w$]*/y;

  var C_LIKE_KEYWORDS = words(
    'abstract as async await base break case catch class const continue default delegate delete do ' +
    'else enum event explicit export extends extern final finally fixed fn for foreach from func function ' +
    'get go goto if impl implements implicit import in init interface internal is let lock loop match mod ' +
    'module mut namespace new of operator out override package params partial private protected pub public ' +
    'readonly record ref required return sealed select set static struct super switch this throw trait try ' +
    'type typeof unsafe use using value var virtual void volatile when where while with yield ' +
    'bool byte char decimal double float int long object sbyte short string uint ulong ushort nint nuint ' +
    'dynamic any number boolean symbol never unknown undefined declare keyof infer satisfies'
  );
  var C_LIKE_LITERALS = words('true false null nil None undefined NaN Infinity');

  var LANGS = {};

  LANGS.clike = {
    rules: [
      ['comment', BLOCK],
      ['comment', LINE_SLASH],
      ['meta', /#\s*(?:region|endregion|if|else|elif|endif|define|undef|pragma|nullable|include)\b.*/y, { bol: true }],
      ['string', /@"(?:[^"]|"")*"?/y],
      ['string', /\$"(?:[^"\\\n]|\\.)*"?/y],
      ['string', DQ],
      ['string', SQ],
      ['string', BT],
      ['meta', /@[A-Za-z_][\w.]*/y],
      ['number', NUM]
    ],
    keywords: C_LIKE_KEYWORDS,
    literals: C_LIKE_LITERALS,
    titles: true
  };

  LANGS.python = {
    rules: [
      ['comment', HASH],
      ['string', /[rRbBuUfF]{0,2}"""[\s\S]*?(?:"""|$)/y],
      ['string', /[rRbBuUfF]{0,2}'''[\s\S]*?(?:'''|$)/y],
      ['string', /[rRbBuUfF]{0,2}"(?:[^"\\\n]|\\.)*"?/y],
      ['string', /[rRbBuUfF]{0,2}'(?:[^'\\\n]|\\.)*'?/y],
      ['meta', /@[A-Za-z_][\w.]*/y],
      ['number', NUM]
    ],
    keywords: words(
      'and as assert async await break class continue def del elif else except finally for from global ' +
      'if import in is lambda match case nonlocal not or pass raise return try while with yield self print'
    ),
    literals: words('True False None'),
    titles: true
  };

  LANGS.shell = {
    rules: [
      ['comment', /<#[\s\S]*?(?:#>|$)/y],
      ['comment', /(?:^|(?<=\s))#.*/y],
      ['string', DQ],
      ['string', SQ],
      ['variable', /\$(?:\{[^}\n]*\}|\([^)\n]*\)|[A-Za-z_][\w:]*|[0-9#?@*$!-])/y],
      ['title', /[A-Z][a-z]+-[A-Z][A-Za-z]+/y],
      ['attr', /(?<=\s)--?[A-Za-z][\w-]*/y],
      ['number', /\b\d+(?:\.\d+)?\b/y]
    ],
    keywords: words(
      'if then else elif fi case esac for while until do done in function return exit break continue ' +
      'local export readonly declare source alias unset shift trap set echo cd sudo ' +
      'begin process end param foreach switch throw try catch finally filter workflow'
    ),
    keywordsCaseInsensitive: true,
    literals: words('true false $true $false $null'),
    titles: false,
    commandTitles: true
  };

  LANGS.xml = {
    rules: [
      ['comment', /<!--[\s\S]*?(?:-->|$)/y],
      ['meta', /<!\[CDATA\[[\s\S]*?(?:\]\]>|$)/y],
      ['meta', /<[!?][^>]*>?/y],
      ['title', /<\/?[A-Za-z_][\w:.-]*/y],
      ['punct', /\/?>/y],
      ['attr', /[A-Za-z_:][\w:.-]*(?=\s*=)/y],
      ['string', DQ],
      ['string', SQ],
      ['variable', /&[#\w]+;/y]
    ],
    keywords: null,
    titles: false
  };

  LANGS.css = {
    rules: [
      ['comment', BLOCK],
      ['comment', LINE_SLASH],
      ['string', DQ],
      ['string', SQ],
      ['keyword', /@[\w-]+/y],
      ['number', /#[0-9a-fA-F]{3,8}\b/y],
      ['attr', /--?[A-Za-z][\w-]*(?=\s*:(?!:))/y],
      ['attr', /[A-Za-z-]+(?=\s*:\s*[^;{}]*;)/y],
      ['title', /[.#][A-Za-z_-][\w-]*/y],
      ['number', /-?(?:\d+\.?\d*|\.\d+)(?:%|[a-zA-Z]+)?/y],
      ['keyword', /!important\b/y]
    ],
    keywords: words('and not only from to inherit initial unset revert auto none'),
    titles: false
  };

  LANGS.json = {
    rules: [
      ['comment', BLOCK],
      ['comment', LINE_SLASH],
      ['attr', /"(?:[^"\\\n]|\\.)*"(?=\s*:)/y],
      ['string', DQ],
      ['number', /-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?/y]
    ],
    keywords: null,
    literals: words('true false null'),
    titles: false
  };

  LANGS.yaml = {
    rules: [
      ['comment', /(?:^|(?<=\s))#.*/y],
      ['meta', /^---$|^\.\.\.$/my, { bol: true }],
      ['title', /\[[^\]\n]*\](?=\s*$)/my, { bol: true }],
      ['attr', /[^\s#:'"\-\[\]{}][^:#\n]*?(?=\s*[:=](?:\s|$))/y, { bol: true }],
      ['attr', /"[^"\n]*"(?=\s*:)/y, { bol: true }],
      ['string', DQ],
      ['string', SQ],
      ['variable', /[&*][\w-]+/y],
      ['keyword', /-(?=[ \t])/y, { bol: true, keepBol: true }],
      ['number', /-?\b\d+(?:\.\d+)?\b/y]
    ],
    keywords: null,
    literals: words('true false null yes no on off ~ True False Null'),
    titles: false
  };

  LANGS.sql = {
    rules: [
      ['comment', /--.*/y],
      ['comment', BLOCK],
      ['string', SQ],
      ['string', DQ],
      ['attr', /\[[^\]\n]*\]/y],
      ['variable', /[@:][A-Za-z_]\w*/y],
      ['number', NUM]
    ],
    keywords: words(
      'select from where and or not in is null like between join inner left right full outer cross on as ' +
      'group by order having limit offset top distinct union all insert into values update set delete ' +
      'create alter drop table view index primary key foreign references constraint default unique check ' +
      'begin commit rollback transaction case when then else end exists with returning desc asc ' +
      'int integer bigint smallint varchar nvarchar char text date datetime timestamp boolean decimal numeric float real'
    ),
    keywordsCaseInsensitive: true,
    literals: words('true false null'),
    titles: true
  };

  LANGS.markdown = {
    rules: [
      ['title', /#{1,6}[ \t].*/y, { bol: true }],
      ['comment', />.*/y, { bol: true }],
      ['keyword', /(?:[-*+]|\d+[.)])(?=[ \t])/y, { bol: true }],
      ['string', /`[^`\n]*`?/y],
      ['attr', /!?\[[^\]\n]*\]\([^)\n]*\)?/y],
      ['keyword', /\*\*[^*\n]+\*\*|__[^_\n]+__/y]
    ],
    keywords: null,
    titles: false
  };

  LANGS.diff = {
    rules: [
      ['meta', /@@.*/y, { bol: true }],
      ['addition', /\+.*/y, { bol: true }],
      ['deletion', /-.*/y, { bol: true }]
    ],
    keywords: null,
    titles: false
  };

  var ALIASES = {
    js: 'clike', javascript: 'clike', jsx: 'clike', mjs: 'clike', cjs: 'clike',
    ts: 'clike', typescript: 'clike', tsx: 'clike',
    cs: 'clike', csharp: 'clike', 'c#': 'clike', fs: 'clike',
    c: 'clike', h: 'clike', cpp: 'clike', 'c++': 'clike', hpp: 'clike', java: 'clike', kotlin: 'clike', kt: 'clike',
    go: 'clike', golang: 'clike', rust: 'clike', rs: 'clike', swift: 'clike', php: 'clike', dart: 'clike', scala: 'clike',
    py: 'python', python: 'python', python3: 'python',
    sh: 'shell', bash: 'shell', shell: 'shell', zsh: 'shell', console: 'shell', shellsession: 'shell',
    ps: 'shell', ps1: 'shell', powershell: 'shell', pwsh: 'shell', bat: 'shell', cmd: 'shell',
    html: 'xml', htm: 'xml', xml: 'xml', xhtml: 'xml', svg: 'xml', xaml: 'xml', csproj: 'xml', vue: 'xml', plist: 'xml',
    css: 'css', scss: 'css', less: 'css', sass: 'css',
    json: 'json', jsonc: 'json', json5: 'json',
    yaml: 'yaml', yml: 'yaml', toml: 'yaml', ini: 'yaml', properties: 'yaml', conf: 'yaml',
    sql: 'sql', mysql: 'sql', postgresql: 'sql', postgres: 'sql', tsql: 'sql', sqlite: 'sql',
    md: 'markdown', markdown: 'markdown', mdx: 'markdown',
    diff: 'diff', patch: 'diff'
  };

  // -------------------------------------------------------------- tokenizer

  function tokenize(text, lang) {
    var out = [];
    var plain = '';
    var i = 0;
    var n = text.length;
    var rules = lang.rules;
    var atBol = true; // only whitespace seen since the last newline

    function flush() {
      if (plain) {
        out.push([null, plain]);
        plain = '';
      }
    }

    function push(cls, s) {
      flush();
      out.push([cls, s]);
    }

    while (i < n) {
      var ch = text.charAt(i);
      var matched = false;

      for (var r = 0; r < rules.length; r++) {
        var rule = rules[r];
        if (rule[2] && rule[2].bol && !atBol) continue;
        var re = rule[1];
        re.lastIndex = i;
        var m = re.exec(text);
        if (m && m[0].length > 0) {
          if (rule[0] === 'punct') {
            flush();
            out.push([null, m[0]]);
          } else {
            push('hljs-' + rule[0], m[0]);
          }
          i += m[0].length;
          atBol = (rule[2] && rule[2].keepBol) || m[0].charAt(m[0].length - 1) === '\n';
          matched = true;
          break;
        }
      }
      if (matched) continue;

      IDENT.lastIndex = i;
      var id = /[A-Za-z_$]/.test(ch) ? IDENT.exec(text) : null;
      if (id) {
        var w = id[0];
        var key = lang.keywordsCaseInsensitive ? w.toLowerCase() : w;
        var prev = out.length ? out[out.length - 1] : null;
        if (lang.literals && (lang.literals[w] || lang.literals[key])) {
          push('hljs-literal', w);
        } else if (lang.keywords && lang.keywords[key]) {
          push('hljs-keyword', w);
        } else if (lang.titles && /^\s*\(/.test(text.slice(i + w.length, i + w.length + 8))) {
          push('hljs-title', w);
        } else if (lang.titles && prev && prev[0] === 'hljs-keyword' && plain === ' ' &&
                   /^(class|interface|struct|record|enum|def|function|func|fn|trait|type|namespace)$/.test(prev[1])) {
          push('hljs-title', w);
        } else if (lang.commandTitles && atBol) {
          push('hljs-title', w);
        } else {
          plain += w;
        }
        i += w.length;
        atBol = false;
        continue;
      }

      plain += ch;
      if (ch === '\n') {
        atBol = true;
      } else if (ch !== ' ' && ch !== '\t' && ch !== '\r') {
        atBol = false;
      }
      i++;
    }
    flush();
    return out;
  }

  function languageOf(el) {
    var classes = ((el.className || '') + ' ' + ((el.parentElement && el.parentElement.className) || '')).split(/\s+/);
    for (var i = 0; i < classes.length; i++) {
      var m = /^(?:language|lang)-(.+)$/i.exec(classes[i]);
      if (m) return m[1].toLowerCase();
    }
    return null;
  }

  function highlightElement(el) {
    if (!el || el.getAttribute('data-highlighted') === 'yes') return;
    var name = languageOf(el);
    var key = name ? ALIASES[name] : null;
    var lang = key ? LANGS[key] : null;
    if (!lang) return;

    var text = el.textContent || '';
    if (text.length > 200000) return; // keep huge blocks responsive

    var tokens = tokenize(text, lang);
    var frag = document.createDocumentFragment();
    for (var t = 0; t < tokens.length; t++) {
      var tok = tokens[t];
      var node = document.createTextNode(tok[1]);
      if (tok[0]) {
        var span = document.createElement('span');
        span.className = tok[0];
        span.appendChild(node);
        frag.appendChild(span);
      } else {
        frag.appendChild(node);
      }
    }
    while (el.firstChild) el.removeChild(el.firstChild);
    el.appendChild(frag);
    el.classList.add('hljs');
    el.setAttribute('data-highlighted', 'yes');
  }

  function highlightAll() {
    var blocks = document.querySelectorAll('pre code');
    for (var i = 0; i < blocks.length; i++) {
      try {
        highlightElement(blocks[i]);
      } catch (e) {
        /* leave this block plain */
      }
    }
  }

  window.hljs = {
    highlightAll: highlightAll,
    highlightElement: highlightElement,
    listLanguages: function () { return Object.keys(ALIASES); },
    _tokenize: function (text, name) {
      var lang = LANGS[ALIASES[name]];
      return lang ? tokenize(text, lang) : [[null, text]];
    }
  };
})();
